CREATE TABLE quiz_version_programs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, quiz_version_id BIGINT UNSIGNED NOT NULL, program_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY quiz_version_programs_version_program_unique (quiz_version_id,program_id), KEY quiz_version_programs_program (program_id), CONSTRAINT quiz_version_programs_version_fk FOREIGN KEY (quiz_version_id) REFERENCES quiz_versions(id) ON DELETE RESTRICT, CONSTRAINT quiz_version_programs_program_fk FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO quiz_version_programs (quiz_version_id,program_id,created_at) SELECT DISTINCT qv.id,p.id,UTC_TIMESTAMP() FROM quiz_versions AS qv INNER JOIN questions AS q ON q.quiz_version_id = qv.id INNER JOIN question_options AS qo ON qo.question_id = q.id INNER JOIN option_weights AS ow ON ow.question_option_id = qo.id INNER JOIN programs AS p ON p.id = ow.program_id;
